SUMMARY = {
 'MKT-IST': T('Research in progress. Province-level activity and macro indicators are recorded as reported by secondary sources; official verification, district research and statutory checks are outstanding.', 'Araştırma sürüyor. İl düzeyinde satış ve makro göstergeler ikincil kaynaklardan aktarıldığı şekliyle kayıtlı; resmî doğrulama, ilçe araştırması ve yasal kontroller tamamlanmadı.', 'البحث جارٍ. مؤشرات النشاط على مستوى الولاية والمؤشرات الكلية مسجّلة كما نقلتها مصادر ثانوية؛ التحقق الرسمي وبحث الأحياء والفحوص القانونية لم تكتمل بعد.'),
 'MKT-DXB': T('Research in progress. Monthly DLD activity and the most active areas are recorded as reported; official verification, developer and project checks and statutory checks are outstanding.', 'Araştırma sürüyor. Aylık DLD hareketleri ve en aktif bölgeler aktarıldığı şekliyle kayıtlı; resmî doğrulama, geliştirici ve proje kontrolleri ile yasal kontroller tamamlanmadı.', 'البحث جارٍ. نشاط دائرة الأراضي والأملاك الشهري والمناطق الأكثر نشاطاً مسجّلة كما نُقلت؛ التحقق الرسمي وفحوص المطوّرين والمشاريع والفحوص القانونية لم تكتمل بعد.'),
 'MKT-AUH': T('Research in progress. H1 2026 activity and the leading investment-zone areas are recorded as reported; ADREC verification, developer and project checks and statutory checks are outstanding.', 'Araştırma sürüyor. 2026 ilk yarı hareketleri ve öne çıkan yatırım bölgeleri aktarıldığı şekliyle kayıtlı; ADREC doğrulaması, geliştirici ve proje kontrolleri ile yasal kontroller tamamlanmadı.', 'البحث جارٍ. نشاط النصف الأول من 2026 ومناطق الاستثمار الرائدة مسجّلة كما نُقلت؛ تحقق مركز أبوظبي العقاري وفحوص المطوّرين والمشاريع والفحوص القانونية لم تكتمل بعد.'),
}

def main():
    s = load('sources'); e = load('evidence'); b = load('research_blocks'); d = load('districts'); m = load('markets')
    keep = lambda recs, pre: [r for r in recs if not r['id'].startswith(pre)]
    s['records'] = keep(s['records'], 'SRC-MR-') + [src(*x) for x in SOURCES]
    e['records'] = [r for r in e['records'] if not r['id'].startswith('EVD-MKT-') and not r['id'].startswith('EVD-DST-')] + EVIDENCE
    b['records'] = [r for r in b['records'] if not r['id'].startswith('RB-MKT-') and not r['id'].startswith('RB-DST-')]
    d['records'] = [r for r in d['records'] if not r['id'].startswith('DST-DXB-') and not r['id'].startswith('DST-AUH-')]
    mk = {r['id']: r for r in m['records']}
    for x in mk.values(): x['research_block_ids'] = []; x['evidence_ids'] = []
    for mid, blocks in BLOCKS.items():
        for dom, cl, cp, note in blocks:
            rid = f'RB-{mid}-' + dom.replace('_', '-')
            b['records'].append({'id': rid, 'subject': M(mid), 'domain': dom, 'research_closure': cl, 'data_completeness': cp, 'last_reviewed': D, 'next_review_trigger': None, 'note': T(note, *TR[note]), 'is_illustrative': False})
            mk[mid]['research_block_ids'].append(rid)
        mk[mid]['last_reviewed'] = D; mk[mid]['summary'] = SUMMARY[mid]; mk[mid]['record_status'] = 'RESEARCH_IN_PROGRESS'
    for x in EVIDENCE: mk[x['subject']['id']]['evidence_ids'].append(x['id'])
    n = {}
    for mid, slug, name, count, sid, period, geo, note in DISTRICTS:
        tag = mid[4:]; did = f'DST-{tag}-' + slug.upper()
        n[mid] = n.get(mid, 0) + 1
        rb = f'RB-DST-{tag}-{slug.upper()}'
        evs = []
        if count is not None:
            eid = f'EVD-DST-{tag}-{n[mid]:04d}'; evs.append(eid)
            e['records'].append(ev(eid, sid, DST(did), 'DISTRICT-SALES-TX', f'{name}: {count} sales transactions in {period} (DLD records, as compiled).', count, 'count', name, period, '2026-10-17', PEND + ' DLD area boundaries differ from marketing community names.'))
        else:
            # a ranking statement without a count: kept as a text claim so the area's listing stays traceable to its source
            eid = f'EVD-DST-{tag}-{n[mid]:04d}'; evs.append(eid)
            e['records'].append(ev(eid, sid, DST(did), 'DISTRICT-ACTIVITY-NOTE', f'{name}: {note}', note, 'text', name, period, None, PEND + ' Ranking statement only; no transaction count or value is recorded.'))
        d['records'].append({'id': did, 'market_id': mid, 'slug': slug, 'name': name, 'admin_level': 'COMMUNITY', 'record_status': 'RESEARCH_IN_PROGRESS', 'research_block_ids': [rb], 'evidence_ids': evs, 'field_states': [], 'is_illustrative': False})
        b['records'].append({'id': rb, 'subject': DST(did), 'domain': 'DISTRICT', 'research_closure': 'CONDITIONAL', 'data_completeness': 'PARTIAL', 'last_reviewed': D, 'next_review_trigger': None, 'note': T(note + ' Location, supply pipeline, rental demand and project-level checks not yet researched.', DTR[note][0] + ' Konum, arz hattı, kira talebi ve proje düzeyi kontroller henüz araştırılmadı.', DTR[note][1] + ' لم يُبحث بعد الموقع وخط العرض والطلب الإيجاري وفحوص المشاريع.'), 'is_illustrative': False})
    for x in (s, e, b, d):
        x['records'].sort(key=lambda r: r['id'])
    for c, j in (('sources', s), ('evidence', e), ('research_blocks', b), ('districts', d), ('markets', m)): save(c, j)
    print('sources', len(SOURCES), 'evidence', len(e['records']), 'blocks', len(b['records']), 'districts', len(d['records']))
main()
